257			hasEntireHook(hooksFile.Hooks.SubagentStop) ||
258			hasEntireHook(hooksFile.Hooks.PreToolUse) ||
259			hasEntireHook(hooksFile.Hooks.PostToolUse) ||
260			hasEntireHook(hooksFile.Hooks.ErrorOccurred)
