263	// GetSupportedHooks returns the normalized lifecycle events this agent supports.
264	// Note: HookNames() returns 8 hooks but GetSupportedHooks() returns only 6.
265	// The two not listed here are:
266	//   - subagentStop: handled by ParseHookEvent (returns SubagentEnd), but there is no
267	//     HookType constant for subagent events (they use EventType instead).
268	//   - errorOccurred: pass-through hook with no lifecycle action (ParseHookEvent returns nil).
269	func (c *CopilotCLIAgent) GetSupportedHooks() []agent.HookType {
270		return []agent.HookType{
271			agent.HookSessionStart,
272			agent.HookSessionEnd,
273			agent.HookUserPromptSubmit,
274			agent.HookStop,
275			agent.HookPreToolUse,
276			agent.HookPostToolUse,
277		}
278	}
